AttachmentSample* ordinary_samples = current_template->secondary_samples;
AttachmentSample* sample = &ordinary_samples[sample_index];
Vec3* anchor = &source_cell->position;
float base_x =
    lateral_scale * (advanced * sample->delta_dir_to_next.x)
    + sample->transform.position.x
    + anchor->x;
float base_y =
    lateral_scale * (advanced * sample->delta_dir_to_next.y)
    + sample->transform.position.y
    + anchor->y;
float base_z =
    advanced * sample->delta_dir_to_next.z
    + sample->transform.position.z
    + anchor->z;
